const items = [];

// Process Reddit Fauxmoi
try {
  const fauxmoi = $('Fetch Reddit Fauxmoi (Pop Global)').first().json;
  if (fauxmoi?.data?.children) {
    for (const post of fauxmoi.data.children) {
      if (post.data.score >= 150 && !post.data.over_18) {
        items.push({
          source: 'reddit-fauxmoi',
          source_id: post.data.id,
          title: post.data.title,
          content: post.data.selftext || post.data.title,
          url: 'https://reddit.com' + post.data.permalink,
          category: 'hollywood-barat',
          score: post.data.score
        });
      }
    }
  }
} catch (e) {}

// Process Reddit Indo
try {
  const indo = $('Fetch Reddit Indonesia (Drama Lokal)').first().json;
  if (indo?.data?.children) {
    for (const post of indo.data.children) {
      if (post.data.score >= 50 && !post.data.over_18) {
        items.push({
          source: 'reddit-indonesia',
          source_id: post.data.id,
          title: post.data.title,
          content: post.data.selftext || post.data.title,
          url: 'https://reddit.com' + post.data.permalink,
          category: 'seleb-lokal',
          score: post.data.score
        });
      }
    }
  }
} catch (e) {}

// Safety Pre-Filter & Anti-Duplication Signature
const forbidden = ['bunuh diri', 'porn', 'bokep', 'telanjang', 'gore', 'mutilasi', 'pedofil'];
const safeItems = items.filter(item => {
  const lower = (item.title + ' ' + item.content).toLowerCase();
  return !forbidden.some(word => lower.includes(word));
});

// Add Entity-Event Signature
safeItems.forEach(item => {
  const cleanTitle = item.title.toLowerCase().replace(/[^a-z0-9]/g, '');
  item.event_signature = cleanTitle.slice(0, 32);
});

return safeItems.slice(0, 3).map(item => ({ json: item }));
